                                u8 **buf = (u8 **) parm;
-                               *buf = malloc(objlen);
-                               if (*buf == NULL) {
-                                       r = SC_ERROR_OUT_OF_MEMORY;
-                                       break;
+                               if (objlen > 0) {
+                                       *buf = malloc(objlen);
+                                       if (*buf == NULL) {
+                                               r = SC_ERROR_OUT_OF_MEMORY;
